// @ts-check
/**
 * The published assets and their checksum manifest (REQ-STARTUP-031, REQ-STARTUP-032, REQ-STARTUP-152 narrowed by
 * PD-STARTUP-012; first-release-plan.md §4.7; ADR-0054's Decision: "the checksums manifest is generated by the release
 * pipeline from the emitted assets").
 *
 * A release directory holds what the release publishes and nothing else: the artifacts of the published platform set,
 * named by `tools/release-naming` alone, one SBOM per published platform key (PD-STARTUP-012, named by the same
 * authority's `sbomName`, never an artifact kind), `SHA256SUMS.txt` over all of them, and `SHA256SUMS.txt.sig` over
 * that. The manifest's format is the naming authority's (`formatChecksumManifest`), the same text the updater parses, so
 * the writer here composes no line of its own.
 *
 * Plain JavaScript with no installed dependency, on purpose: the signing job runs this tool without `pnpm install`, so
 * the only modules it reaches are Node's own and two TypeScript files of erasable syntax loaded by Node's type stripping
 * (the naming authority, and the updater's key set in `signing.mjs`).
 */
import { createHash } from 'node:crypto';
import { closeSync, existsSync, openSync, readdirSync, readFileSync, readSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  artifactName,
  CHECKSUM_MANIFEST_NAME,
  CHECKSUM_SIGNATURE_NAME,
  formatChecksumManifest,
  KINDS_BY_PLATFORM,
  parseChecksumManifest,
  sbomName,
} from '../release-naming/src/index.ts';

/**
 * The platform keys a release publishes for: `windows-x64` alone while `PD-STARTUP-001` stands. Withdrawing the
 * directive is the one change that widens this list (and the workflow's matrix), and it lands only once IC-3 and IC-8
 * are discharged.
 */
export const PUBLISHED_PLATFORMS = Object.freeze(['windows-x64']);

/** Every artifact a release of `version` publishes for `platforms`, named by the authority, in matrix order. */
/** @param {string} version @param {readonly string[]} [platforms] @returns {import('./assets.d.mts').ReleaseAsset[]} */
export function expectedAssets(version, platforms = PUBLISHED_PLATFORMS) {
  return platforms.flatMap((platform) => {
    const kinds = KINDS_BY_PLATFORM[/** @type {keyof typeof KINDS_BY_PLATFORM} */ (platform)];
    if (!kinds) throw new Error(`"${platform}" is not a platform key of REQ-STARTUP-030`);
    return kinds.map((kind) => ({ platform: /** @type {import('@rotaris/release-naming').PlatformKey} */ (platform), kind, name: artifactName(version, kind) }));
  });
}

/**
 * PD-STARTUP-012: the SBOM each published platform key publishes beside its artifacts, one per key, named by the
 * authority's `sbomName`. Kept apart from `expectedAssets` on purpose: an SBOM is a published asset the manifest lists
 * and the signature covers, never an artifact a platform builds, launches or offers as an update.
 */
/** @param {string} version @param {readonly string[]} [platforms] @returns {import('./assets.d.mts').ReleaseSbom[]} */
export function expectedSboms(version, platforms = PUBLISHED_PLATFORMS) {
  return platforms.map((platform) => ({ platform: /** @type {import('@rotaris/release-naming').PlatformKey} */ (platform), name: sbomName(version, platform) }));
}

/** The SHA-256 of a file in lower-case hexadecimal, read 1 MiB at a time so an installer is never held whole. */
/** @param {string} path @returns {string} */
export function sha256File(path) {
  const hash = createHash('sha256');
  const chunk = Buffer.allocUnsafe(1024 * 1024);
  const fd = openSync(path, 'r');
  try {
    for (;;) {
      const read = readSync(fd, chunk, 0, chunk.length, null);
      if (read === 0) break;
      hash.update(chunk.subarray(0, read));
    }
  } finally {
    closeSync(fd);
  }
  return hash.digest('hex');
}

/**
 * What a release directory holds, read against the names the authority renders: the artifacts it expects and found,
 * the ones it expects and did not find, the same two for the SBOMs (PD-STARTUP-012), and every other file. The manifest
 * and its signature are neither asset nor foreign.
 */
/** @param {string} dir @param {string} version @param {readonly string[]} [platforms] */
export function readReleaseDirectory(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const expected = expectedAssets(version, platforms);
  const expectedSbomSet = expectedSboms(version, platforms);
  const present = new Set(readdirSync(dir).filter((name) => statSync(join(dir, name)).isFile()));
  const assets = expected.filter((a) => present.has(a.name));
  const missing = expected.filter((a) => !present.has(a.name));
  const sboms = expectedSbomSet.filter((s) => present.has(s.name));
  const missingSboms = expectedSbomSet.filter((s) => !present.has(s.name));
  const known = new Set([...expected.map((a) => a.name), ...expectedSbomSet.map((s) => s.name), CHECKSUM_MANIFEST_NAME, CHECKSUM_SIGNATURE_NAME]);
  const foreign = [...present].filter((name) => !known.has(name)).sort();
  return { assets, missing, sboms, missingSboms, foreign };
}

/** @param {readonly string[]} foreign @param {string} version */
function foreignProblems(foreign, version) {
  return foreign.map(
    (name) =>
      `REQ-STARTUP-152: "${name}" is neither an artifact name nor an SBOM name tools/release-naming renders for ${version} and the published platforms; a release publishes nothing the naming scheme does not name (PD-STARTUP-012 admits the SBOM alone)`,
  );
}

/** @param {readonly import('./assets.d.mts').ReleaseSbom[]} missingSboms */
function missingSbomProblems(missingSboms) {
  return missingSboms.map((s) => `PD-STARTUP-012: ${s.name} is missing; ${s.platform} publishes its SBOM beside its artifacts, listed in ${CHECKSUM_MANIFEST_NAME}`);
}

/**
 * REQ-STARTUP-032: writes `SHA256SUMS.txt` into `dir` over every asset the directory holds — the artifacts and the
 * SBOMs, never itself, never the signature — and removes any earlier signature, which was made over other bytes. A file
 * the naming scheme does not name refuses the step with nothing written, and so does a missing SBOM: PD-STARTUP-012
 * refuses a release lacking the SBOM of a published platform key at this step, so no signature is ever made over a
 * manifest without it. An expected artifact that is absent is not this step's refusal: the manifest covers what the
 * release publishes, and `verifyReleaseDirectory` is where an incomplete release fails (it fails a missing SBOM too).
 */
/** @param {string} dir @param {string} version @param {readonly string[]} [platforms] */
export function writeChecksumManifest(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const { assets, sboms, missingSboms, foreign } = readReleaseDirectory(dir, version, platforms);
  if (foreign.length > 0 || missingSboms.length > 0) return { ok: false, problems: [...foreignProblems(foreign, version), ...missingSbomProblems(missingSboms)] };
  if (assets.length === 0) return { ok: false, problems: [`REQ-STARTUP-032: ${dir} holds no artifact of ${version} to list`] };
  const entries = [...assets, ...sboms].map((a) => ({ name: a.name, sha256: sha256File(join(dir, a.name)) }));
  const text = formatChecksumManifest(entries);
  writeFileSync(join(dir, CHECKSUM_MANIFEST_NAME), text);
  rmSync(join(dir, CHECKSUM_SIGNATURE_NAME), { force: true });
  return { ok: true, entries: parseChecksumManifest(text), text };
}

/**
 * The checksum half of §5's gate ("`SHA256SUMS.txt` covers every asset, and every digest matches"): every problem, none
 * when the directory is a complete release of `version` — its artifacts and its SBOMs — whose manifest is the authority's
 * exact rendering of them. The signature half is `verifyReleaseSignature` (`signing.mjs`).
 */
/** @param {string} dir @param {string} version @param {readonly string[]} [platforms] @returns {string[]} */
export function verifyReleaseDirectory(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const problems = [];
  const { assets, missing, sboms, missingSboms, foreign } = readReleaseDirectory(dir, version, platforms);
  for (const a of missing) {
    const why = a.kind === 'portable' ? ' (the portable is assembled around the launcher stub of first-release-plan.md §4.5)' : '';
    problems.push(`REQ-STARTUP-031: ${a.name} is missing; ${a.platform} publishes ${KINDS_BY_PLATFORM[/** @type {keyof typeof KINDS_BY_PLATFORM} */ (a.platform)].join(' and ')}${why}`);
  }
  problems.push(...missingSbomProblems(missingSboms));
  problems.push(...foreignProblems(foreign, version));
  const manifestPath = join(dir, CHECKSUM_MANIFEST_NAME);
  if (!existsSync(manifestPath)) {
    problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} is missing; a release publishing no manifest is refused as unverifiable`);
    return problems;
  }
  const text = readFileSync(manifestPath, 'utf8');
  const listed = parseChecksumManifest(text);
  if (formatChecksumManifest(listed) !== text) {
    problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} is not in the one format (one "<sha256>  <filename>" line per asset, lower-case digest, two spaces, sorted by filename, LF)`);
  }
  const byName = new Map(listed.map((e) => [e.name, e.sha256]));
  for (const self of [CHECKSUM_MANIFEST_NAME, CHECKSUM_SIGNATURE_NAME]) {
    if (byName.has(self)) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} lists ${self}; it lists neither itself nor the signature`);
  }
  const published = [...assets, ...sboms];
  for (const a of published) {
    const want = byName.get(a.name);
    if (want === undefined) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} does not list ${a.name}`);
    else if (want !== sha256File(join(dir, a.name))) problems.push(`REQ-STARTUP-032: the digest ${CHECKSUM_MANIFEST_NAME} lists for ${a.name} does not match the file`);
  }
  const held = new Set(published.map((a) => a.name));
  for (const name of byName.keys()) {
    if (name === CHECKSUM_MANIFEST_NAME || name === CHECKSUM_SIGNATURE_NAME) continue;
    if (!held.has(name)) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} lists ${name}, which the release does not publish`);
  }
  return problems;
}
